 <script>
     $('.lowQuantityError').hide();
     $('.less-quantity').hide();
     $(document).ready(function() {
         console.log("Document ready!");
         var totalAmount = 0;
         var totalProducts = 0;
         var cartData = [];
         updateTotalItemDisplay();

         $(".futured-product-add-tocart-btn").on("click", function() {
             var button = $(this);
             var originalText = button.text();
             button.text("Adding...");

             var quantityField = $(this).closest(".row").find(".prtoduct-vieww-counter-inp").val();
             var quantity = 1;
             var title = $(this).data("title");
             var amount = parseFloat($(this).data("amount"));
             var featuredImage = $(this).data("featured_image");
             var pId = $(this).data("p_id");
             var gst = $(this).data("gst");

             if (quantityField !== undefined) {
                 quantity = quantityField;
             } else {
                 quantity = 1;
             }
             var existingProductIndex = cartData.findIndex(product => product.pId === pId);

             updateTotalItemDisplay();
             $.ajax({
                 url: "/update-cart",
                 method: "POST",
                 headers: {
                     "X-CSRF-TOKEN": $('meta[name="csrf-token"]').attr("content")
                 },
                 data: {
                     pId: pId,
                     title: title,
                     amount: amount,
                     featuredImage: featuredImage,
                     gst: gst,
                     quantity: quantity
                 },
                 success: function(response) {
                     if (response.status == false) {
                         $('.lowQuantityError').show();
                         button.text(originalText);
                         $("html, body").animate({
                             scrollTop: $(".lowQuantityError").offset().top
                         }, "slow");
                         setTimeout(function() {
                             $('.lowQuantityError').hide();
                         }, 3000);

                     } else {
                         if (existingProductIndex !== -1) {
                             cartData[existingProductIndex].quantity + quantity;
                         } else {
                             var product = {
                                 title: title,
                                 amount: amount,
                                 pId: pId,
                                 featuredImage: featuredImage,
                                 quantity: quantity,
                                 productGst: 0
                             };
                             if (gst !== null) {
                                 product.gst = gst;
                             }
                             cartData.push(product);
                         }
                         $('.shoppingPage-total_amount').text('$' + response.amounts
                             .totalAmount);
                         //  let subtotal = response.amounts
                         $('.shippingPage-subTotal').text('$' + response.amounts.subTotal);
                         $('.shippingPage-gst').text('$' + response.amounts.gst);
                         updateTotalItemDisplay();
                         button.text(originalText);
                     }
                 }
             });
         });

         var ajaxInProgress = false;
         $(document).on("click", ".cart-cross-icon", function() {
             console.log("Close product icon clicked!");
             if (!ajaxInProgress) {
                 ajaxInProgress = true;

                 var pId;
                 var removedAmount = parseFloat($(this).closest(".row").find(".cart-amount").text());
                 var title = $(this).closest(".row").find(".cart-title").text().trim(); // Trim the title
                 var productId = $(this).data('product-id');
                 if (productId !== undefined) {
                     pId = productId;
                 } else {
                     pId = $(this).closest(".row").find(".cart-pId").text().trim();
                 }
                 totalAmount -= removedAmount;
                 totalProducts--;

                 $(this).closest(".row").remove();

                 cartData = cartData.filter(function(product) {
                     return product.title.trim() !==
                         title; // Trim the product title for comparison
                 });

                 console.log("Item removed from cart: " + title);
                 console.log("Cart data:", cartData);

                 updateTotalItemDisplay();
                 $.ajax({
                     url: "/update-cart",
                     method: "POST",
                     headers: {
                         "X-CSRF-TOKEN": $('meta[name="csrf-token"]').attr("content")
                     },
                     data: {
                         pIdToRemove: pId
                     },
                     success: function(response) {
                         let totalGst = parseInt(response.amounts.subTotal) - parseInt(
                             response.amounts.gst);
                         $('.shoppingPage-total_amount').text('$' + response.amounts
                             .totalAmount);
                         $('.shippingPage-subTotal').text('$' + totalGst);
                         $('.shippingPage-gst').text('$' + response.amounts.gst);
                         updateTotalItemDisplay();
                         ajaxInProgress = false;
                     },
                     error: function() {
                         ajaxInProgress = false;
                     }
                 });
                 if (window.location.href == "{{ url('/') }}/shopping-cart") {
                     window.location.href = window.location.href;
                 }
             }
         });

         // Function to update the displayed total amount and total products
         function updateTotalItemDisplay() {
             var cartTotal = cartData.reduce(function(total, product) {
                 return total + product.amount;
             }, 0);
             console.log(cartTotal.toFixed(2));

             $(".sub_total").text("$" + cartTotal.toFixed(2));
             $.ajax({
                 url: "{{ route('total-cart-items') }}",
                 method: 'GET',
                 cache: false,
                 success: function(response) {
                     $(".topbar-cart-no").text(response);
                     $('.shoppingPage-cart-no').text(response);
                 }
             })
         }
         $('.decreameant-btn').click(function() {
             var pId = $(this).data("product-id");
             var current_value = $(this).siblings('.demoInput' + pId).val();
             if (current_value > 1) {
                 var decreaseQuantity = parseInt(current_value) - 1;
                 $.ajax({
                     url: "/update-cart",
                     method: "POST",
                     headers: {
                         "X-CSRF-TOKEN": $('meta[name="csrf-token"]').attr("content")
                     },
                     data: {
                         pId: pId,
                         decreaseQuantity: decreaseQuantity
                     },
                     success: function(response) {
                         if (response.status) {
                             $('.decreameant-btn').siblings('.demoInput' + pId).val(
                                 parseFloat(
                                     current_value) - 1);
                             var matchedProduct = null;
                             for (var i = 0; i < response.data.length; i++) {
                                 if (response.data[i].pId == pId) {
                                     matchedProduct = response.data[i];
                                     break;
                                 }
                             }
                             $('.shippingPage-product-total' + matchedProduct.pId).text(
                                 '$ ' +
                                 parseInt(matchedProduct.amount) * parseInt(
                                     matchedProduct
                                     .quantity));
                             let totalGst = parseInt(response.amounts.subTotal) - parseInt(
                                 response.amounts.gst);
                             $('.shoppingPage-total_amount').text('$ ' + response.amounts
                                 .totalAmount);
                             $('.shippingPage-subTotal').text('$ ' + totalGst);
                             $('.shippingPage-gst').text('$ ' + response.amounts.gst);
                             updateTotalItemDisplay();
                             ajaxInProgress = false;
                         } else {
                             $('.less-quantity.' + pId).append(`
                             <span class="text-danger"><b>` + response.message + `</b></span>
                             `);
                             setTimeout(function() {
                                 $('.less-quantity').hide();
                             }, 3000);
                         }
                     },
                     error: function() {
                         ajaxInProgress = false;
                     }
                 });
             }
         });
         $('.increment-btn').click(function() {
             var pId = $(this).data("product-id");
             var current_value = $(this).siblings('.demoInput' + pId).val();
             if (current_value < 100) {
                 var increaseQuantity = parseInt(current_value) + parseInt(1);
                 $.ajax({
                     url: "/update-cart",
                     method: "POST",
                     headers: {
                         "X-CSRF-TOKEN": $('meta[name="csrf-token"]').attr("content")
                     },
                     data: {
                         pId: pId,
                         increaseQuantity: increaseQuantity
                     },
                     success: function(response) {
                         if (response.status) {
                             $('.increment-btn').siblings('.demoInput' + pId).val(parseFloat(
                                 current_value) + 1);
                             var matchedProduct = null;
                             for (var i = 0; i < response.data.length; i++) {
                                 if (response.data[i].pId == pId) {
                                     matchedProduct = response.data[i];
                                     break;
                                 }
                             }
                             $('.shippingPage-product-total' + matchedProduct.pId).text(
                                 '$ ' +
                                 parseInt(matchedProduct.amount) * parseInt(
                                     matchedProduct
                                     .quantity));
                             let totalGst = parseInt(response.amounts.subTotal) - parseInt(
                                 response.amounts.gst);
                             $('.shoppingPage-total_amount').text('$ ' + response.amounts
                                 .totalAmount);
                             $('.shippingPage-subTotal').text('$ ' + totalGst);
                             $('.shippingPage-gst').text('$ ' + response.amounts.gst);
                             updateTotalItemDisplay();
                             ajaxInProgress = false;
                         } else {
                             $('.less-quantity' + pId).append(`
                             <span class="text-danger"><b>` + response.message + `</b></span>
                             `);
                             setTimeout(function() {
                                 $('.less-quantity' + pId).hide();
                             }, 3000);
                         }
                     },
                     error: function() {
                         ajaxInProgress = false;
                     }
                 });
             }
         });
     });


     // offcanvas
     $(document).ready(function() {
         $(document).on("click", ".offcanvase_btn, .remove_product_cart", function() {
             console.log("Icon clicked!");

             $.ajax({
                 url: "{{ route('show-Cart-data') }}",
                 method: "POST",
                 headers: {
                     "X-CSRF-TOKEN": $('meta[name="csrf-token"]').attr("content")
                 },
                 success: function(response) {
                     // Update your offcanvas content with the response data
                     $(".car_canvas_body").html(response.html);
