     });

     //  Nauman Code Starts
     function updateAddress(id) {
         $.ajax({
             url: '/shipping-address/update/' + id,
             type: 'GET',
             data: {
                 _token: '{{ csrf_token() }}'
             },
             success: function(response) {
                 console.log(JSON.stringify(response));
                 $('#id').val(response.id);
                 $('#user_id').val(response.user_id);
                 $('#f_name').val(response.f_name);
                 $('#l_name').val(response.l_name);
                 $('#company').val(response.company);
                 $('#phone').val(response.phone);
                 $('#street_address').val(response.street_address);
                 $('#post_code').val(response.post_code);
                 $('#suburb').val(response.suburb);
                 $('#city').val(response.city);
                 $('#state').val(response.state);
                 $('#address_type').val(response.address_type);
                 $('.addressModal').modal('show');
             },
             error: function(xhr, status, error) {
                 alert('Error occurred while deleting the product: ' + xhr
                     .responseText);
             }
         });
     }
